export function parseCSV(text){
  text=text.replace(/^\uFEFF/,'');const rows=[];let row=[],cell='',quoted=false;
  for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else if(quoted||cell==='')quoted=!quoted;else throw Error('Unexpected quote in CSV');}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x!==''))rows.push(row);row=[];cell='';}else cell+=c;}
  if(quoted)throw Error('Unclosed CSV quote');if(cell||row.length){row.push(cell);rows.push(row);}if(!rows.length)throw Error('Empty CSV');const headers=rows.shift().map(h=>h.trim());if(new Set(headers).size!==headers.length)throw Error('Duplicate CSV columns');return {headers,rows:rows.map(r=>{if(r.length!==headers.length)throw Error('CSV row has the wrong number of columns');return Object.fromEntries(headers.map((h,i)=>[h,r[i].trim()]));})};
}
export function readOwnership(text,territories,teams){const {headers,rows}=parseCSV(text);for(const key of ['territory_id','claimed_by','locked_by'])if(!headers.includes(key))throw Error('Missing ownership column: '+key);const ids=new Set(territories.map(t=>t.id)),valid=new Set(teams.map(t=>t.id));const state={};for(const r of rows){if(!ids.has(r.territory_id))throw Error('Unknown territory: '+r.territory_id);if(state[r.territory_id])throw Error('Duplicate territory: '+r.territory_id);for(const k of ['claimed_by','locked_by'])if(r[k]&&!valid.has(r[k]))throw Error('Unknown team: '+r[k]);state[r.territory_id]={claimed:r.claimed_by,locked:r.locked_by};}if(Object.keys(state).length!==territories.length)throw Error('Ownership sheet must contain every territory');return state;}
export function readHistory(text,territories,teams){const {headers,rows}=parseCSV(text);for(const key of ['team','territory_id','reveal_order','status'])if(!headers.includes(key))throw Error('Missing history column: '+key);const ids=new Set(territories.map(t=>t.id)),valid=new Set(teams.map(t=>t.id)),seen=new Set(),orders=new Set();for(const r of rows){if(!valid.has(r.team)||!ids.has(r.territory_id))throw Error('Unknown history team or territory');const key=r.team+'/'+r.territory_id;if(seen.has(key))throw Error('Duplicate team/territory history row');seen.add(key);if(!['Not opened','Active','Succeeded','Failed','Abandoned'].includes(r.status))throw Error('Invalid challenge status');if(r.status==='Not opened'){if(r.reveal_order)throw Error('Unopened challenge has a reveal order');}else{if(!/^[1-9]\d*$/.test(r.reveal_order))throw Error('Opened challenge needs a positive reveal order');const order=r.team+'/'+r.reveal_order;if(orders.has(order))throw Error('Duplicate reveal order for a team');orders.add(order);}r.order=Number(r.reveal_order)||0;}return rows;}
export function owner(state){return state?.locked||state?.claimed||'';}
export function eligibility(history,team,territory,retryable){const records=history.filter(r=>r.team===team),active=records.filter(r=>r.status==='Active'),record=records.find(r=>r.territory_id===territory);if(active.length>1)return {allowed:false,message:'Your sheet has multiple active challenges. Resolve them before revealing another.'};if(active.length&&active[0].territory_id!==territory)return {allowed:false,message:'Resolve your active challenge before revealing another.'};if(record?.status==='Succeeded')return {allowed:true,revisit:true};if(record?.status==='Failed'||record?.status==='Abandoned'){if(!retryable)return {allowed:false,message:'This challenge does not allow retries.'};if(records.some(r=>r.order>record.order))return {allowed:false,message:'You opened another challenge. This challenge can no longer be retried.'};}return {allowed:true};}
